CREATE POLICY "Project participants read project files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'project-files' AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id::text = (storage.foldername(name))[1] AND (p.client_id = auth.uid() OR p.professional_id = auth.uid() OR private.has_role(auth.uid(),'admin'))));
CREATE POLICY "Project team uploads project files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'project-files' AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id::text = (storage.foldername(name))[1] AND (p.professional_id = auth.uid() OR private.has_role(auth.uid(),'admin'))));
CREATE POLICY "Project team deletes project files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'project-files' AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id::text = (storage.foldername(name))[1] AND (p.professional_id = auth.uid() OR private.has_role(auth.uid(),'admin'))));